      lbl(S, 'l1', 19.0, 1.8, ['스타터 넷을 더하자 기동 시간이 약 3배가 됐어요', 'adding four starters roughly tripled startup time'], 'w', 1, { w: 12.4 });
      rbars(S, 'b2', 3.2, [['web beans', 1.97, 'ok', '146'], ['full beans', 5.0, 'warn', '370']], 2);
      lbl(S, 'l2', 19.0, 4.45, ['빈은 146개에서 370개, 켜진 자동 설정은 16개에서 65개였어요', 'beans went from 146 to 370, active auto-configurations from 16 to 65'], 'a', 2, { w: 12.4 });
