      lbl(S, 'l2', 19.0, 3.7, ['가상 스레드를 켜도 3,167ms로 같았어요, 막힌 곳이 커넥션 풀이라서예요', 'virtual threads gave the same 3,167 ms, the bottleneck being the pool'], 'r', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.1, ['풀을 30으로 늘리자 60개가 1,193ms에 끝났어요', 'raising the pool to 30 finished 60 in 1,193 ms'], 'g', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['가상 스레드는 커넥션을 늘려 주지 않아요, 트랜잭션은 짧게', 'virtual threads add no connections; keep transactions short'], 'a', 4, { w: 16.0 });
