      lbl(S, 'l3', 19.0, 4.6, ['immediate로 바꾸자 96ms에 꺼졌고 진행 중인 요청은 실패했어요', 'with immediate it exited in 96 ms and the in-flight request failed'], 'r', 3, { w: 12.4 });
