function sBatchT() {
  return CW('sb-batch-insert', {
    code: ['saveAll(10,000 entities)   // one transaction', 'hibernate.jdbc.batch_size=50', 'IDENTITY      prepared 10,000   233–251 ms', 'SEQUENCE(50)  prepared 201      139–172 ms', '// 201 = 200 sequence calls + 1 insert'],
    hl: [[2, 1, 'danger'], [3, 1, 'ok'], [4, 1, 'accent'], null],
    draw: (S) => {
      rbars(S, 'b1', .5, [['IDENTITY', 5.0, 'danger', '10,000'], ['SEQUENCE', .1, 'ok', '201']], 1);
      lbl(S, 'l1', 19.0, 1.8, ['batch_size를 줘도 IDENTITY는 insert를 1만 번 따로 준비했어요', 'even with batch_size, IDENTITY prepared 10,000 separate inserts'], 'r', 1, { w: 12.4 });
      rbars(S, 'b2', 3.2, [['IDENTITY', 5.0, 'warn', '233–251 ms'], ['SEQUENCE', 3.2, 'ok', '139–172 ms']], 2);
      lbl(S, 'l2', 19.0, 4.45, ['SEQUENCE는 insert 문 하나를 50개씩 묶어 다시 썼고 30~40% 빨랐어요', 'SEQUENCE reused one insert in batches of 50 and was 30 to 40% faster'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.1, ['IDENTITY는 insert마다 DB가 만든 id를 받아야 해서 묶을 수 없어요', 'IDENTITY must get the DB-made id after each insert, so it cannot batch'], 'a', 3, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['대량 저장은 SEQUENCE와 batch_size로 묶어요', 'batch bulk saves with SEQUENCE plus batch_size'], 'a', 4, { w: 16.0 });
    },
    notes: [['엔티티 1만 개를 한 트랜잭션에서 saveAll로 저장했어요 · id 생성 방식만 IDENTITY와 SEQUENCE(allocationSize 50)로 바꿔 비교했어요 · Hibernate 통계로 준비된 SQL 문 수를 세고, SQL 로그도 함께 봤어요', '10,000 entities were saved with saveAll in one transaction, changing only the id generation between IDENTITY and SEQUENCE with allocationSize 50, counting prepared statements with Hibernate statistics and reading the SQL log as well'], ['hibernate.jdbc.batch_size=50을 줘도 IDENTITY는 준비된 문장이 10,000개였어요 · insert를 하나씩 보냈어요 · 두 번의 실행에서 데운 뒤 232.8~251.4ms였어요', 'even with hibernate.jdbc.batch_size=50, IDENTITY prepared 10,000 statements, sending inserts one by one, in 232.8 to 251.4 ms after warmup across two runs'], ['SEQUENCE는 201개였어요 · 시퀀스 조회 select next value가 50개마다 1번씩 200번, 그리고 한 번 준비해 50개씩 묶어 다시 쓴 insert 문 1개예요 · 139.2~171.5ms로 30~40% 빨랐어요 · batch_size가 없으면 SEQUENCE도 10,200개, 235.1~242.1ms였어요', 'SEQUENCE prepared 201, the sequence call select next value 200 times, once per 50 ids, plus one insert statement prepared once and reused in batches of 50, taking 139.2 to 171.5 ms, 30 to 40% faster, while without batch_size SEQUENCE also prepared 10,200 and took 235.1 to 242.1 ms'], ['IDENTITY는 데이터베이스가 insert할 때 id를 만들어요 · Hibernate는 영속성 컨텍스트에 넣으려고 insert마다 바로 실행해 id를 받아야 해요 · 그래서 묶을 수 없어요 · 같은 프로세스의 H2라 차이가 이 정도이고, 네트워크 너머 DB라면 왕복 수 차이가 더 크게 보여요', 'with IDENTITY the database creates the id on insert, so Hibernate must execute each insert immediately to get the id for its persistence context and cannot batch, and while an in-process H2 keeps the gap this small, the difference in round trips shows far more against a database across the network']],
    fin: [['IDENTITY는 묶이지 않아요', 'IDENTITY does not batch', 'sbx-xs sbx-a'], ['10,000번 대 201번', '10,000 versus 201'], ['SEQUENCE + batch_size', 'SEQUENCE plus batch_size']],
    caps: [['1만 개 저장', 'Saving 10,000'], ['IDENTITY', 'IDENTITY'], ['SEQUENCE', 'SEQUENCE'], ['묶이지 않는 이유', 'Why it cannot batch'], ['배치 insert', 'Batch inserts']]
  });
}

